use num_bigint::BigUint;use num_traits::{One,Zero,ToPrimitive};use serde_json::json;use std::fs;
const R:&str="/home/ubuntu/src/zopro-perf-work/loose-complex-square176";const B:u128=1u128<<52;
fn limbs(x:&BigUint)->[u128;5]{let mask=BigUint::from((B-1)as u64);std::array::from_fn(|i|((x>>(52*i))& &mask).to_u64().unwrap()as u128)}
fn integer(t:&[u128])->BigUint{t.iter().enumerate().map(|(i,&x)|BigUint::from(x)<<(52*i)).sum()}
fn prepare(a:&BigUint,b:&BigUint,p:&BigUint)->(BigUint,BigUint){let aa=limbs(a);let bb=limbs(b);let pp=limbs(&(p<<1usize));let mut s=[0u128;5];let mut d=[0u128;5];let mut carry=0u128;for j in 0..5{let v=aa[j]+bb[j]+carry;s[j]=v&(B-1);carry=v>>52;}assert_eq!(carry,0);let mut carry=0i128;for j in 0..5{let v=pp[j]as i128+aa[j]as i128-bb[j]as i128+carry;carry=v>>52;d[j]=(v&(B as i128-1))as u128;}assert_eq!(carry,0);let s=integer(&s);let d=integer(&d);assert_eq!(s,a+b);assert_eq!(d,(p<<1usize)+a-b);assert!(s<=(p<<2usize)&&d<=(p<<2usize));(s,d)}
fn cios(s:&BigUint,d:&BigUint,p:&BigUint,mixed:bool,peak:&mut u128)->BigUint{let a=limbs(s);let b=limbs(d);let pp=limbs(p);let m52=BigUint::one()<<52usize;let inverse=p.modpow(&((&m52>>1usize)-BigUint::one()),&m52);let inv=((&m52-inverse)%&m52).to_u64().unwrap()as u128;let mut t=[0u128;6];for i in 0..5{let before=integer(&t)+s*BigUint::from(b[i]);for j in 0..5{let product=a[j]*b[i];t[j]+=product&(B-1);t[j+1]+=product>>52;}let w=if mixed&&i==4{48}else{52};let unit=1u128<<w;let m=t[0]*inv&(unit-1);let correction=if w==48{((m<<4)*pp[0])>>52}else{(m*pp[0])>>52};let low=((t[0]+unit-1)>>w)+correction;assert_eq!(low,(t[0]+m*pp[0])>>w);assert_eq!((t[0]+m*pp[0])&(unit-1),0);for j in 1..5{let product=m*pp[j];t[j]+=product&(B-1);t[j+1]+=product>>52;}for x in t{*peak=(*peak).max(x);assert!(x<1u128<<61);}if w==48{let mask=unit-1;t=[low+((t[1]&mask)<<4),(t[1]>>48)+((t[2]&mask)<<4),(t[2]>>48)+((t[3]&mask)<<4),(t[3]>>48)+((t[4]&mask)<<4),(t[4]>>48)+(t[5]<<4),0];}else{t[1]+=low;t=[t[1],t[2],t[3],t[4],t[5],0];}assert_eq!(integer(&t),(before+BigUint::from(m)*p)>>w);for x in t{*peak=(*peak).max(x);assert!(x<1u128<<61);}}
for j in 0..4{let carry=t[j]>>52;t[j]&=B-1;t[j+1]+=carry;}assert_eq!(t[5],0);integer(&t)}
fn main(){assert!(!std::path::Path::new(&format!("{R}/model.json")).exists());let fields=[("Fq","21888242871839275222246405745257275088696311157297823662689037894645226208583"),("Fr","21888242871839275222246405745257275088548364400416034343698204186575808495617")];let mut all=0u64;let mut peak=0u128;let mut reports=Vec::new();for(name,decimal)in fields{let p=BigUint::parse_bytes(decimal.as_bytes(),10).unwrap();let two=&p<<1usize;let four=&p<<2usize;let nine=&p*&p*9u32;let edges=[BigUint::zero(),BigUint::one(),BigUint::from(2u32),&p-1u32,p.clone(),&p+1u32,&two-1u32,two.clone()];let mut pairs=Vec::new();for a in&edges{for b in&edges{pairs.push((a.clone(),b.clone()));}}for bit in 0usize..255{let x:BigUint=BigUint::one()<<bit;for dx in[-1i32,0,1]{let v:BigUint=if dx<0{&x-1u32}else{&x+dx as u32};if v<=two{pairs.push((v.clone(),&two-&v));pairs.push((v.clone(),v));}}}let mut state=0xa4093822299f31d0u64;let mut next=||{let words=(0..4).map(|_|{state^=state<<13;state^=state>>7;state^=state<<17;state}).collect::<Vec<_>>();BigUint::new(words.into_iter().flat_map(|w|[w as u32,(w>>32)as u32]).collect())%(&two+1u32)};for _ in 0..4096{pairs.push((next(),next()));}
for mixed in[true,false]{let radix=BigUint::one()<<if mixed{256usize}else{260};assert!(four<radix);assert!(!mixed||(&p*9u32)<(&radix*2u32));assert!(mixed||(&p*64u32)<radix);let pinv=p.modpow(&((&radix>>1usize)-1u32),&radix);let rinv=radix.modpow(&(&p-2u32),&p);let mut corrected=0;let mut prepare_checks=0;let mut run=|a:&BigUint,b:&BigUint|{let(s,d)=prepare(a,b,&p);let t=&s*&d;assert!(t<=nine);assert_eq!(&t+(b+&p)*(b+&p),(a+&p)*(a+&p)+b*&p*4u32);let got=cios(&s,&d,&p,mixed,&mut peak);let k=(&radix-((&t*&pinv)%&radix))%&radix;let expected=(&t+k*&p)/&radix;assert_eq!(got,expected);assert!(got<four);let out=if mixed&&got>=two{corrected+=1;&got-&two}else{got.clone()};assert!(out<two);let expected_field=(a*a+&p*&p*4u32-b*b)%&p*&rinv%&p;assert_eq!(&out%&p,expected_field);all+=1;prepare_checks+=2;out};for(a,b)in&pairs{run(a,b);}let(mut a,mut b)=(&two-17u32,&p+31u32);for _ in 0..1024{let out=run(&a,&b);a=b;b=out;}reports.push(json!({"field":name,"radix_bits":if mixed{256}else{260},"pairs":pairs.len(),"chain_outputs":1024,"prepared_operand_checks":prepare_checks,"final_corrections":corrected}));}}
let out=json!({"complete":true,"outputs":all,"row_identity_comparisons":all*5,"reports":reports,"maximum_observed_coefficient":peak.to_string(),"correlated_product_bound":"(a+b)(2p+a-b)=(a+p)^2-(b-p)^2<=9p^2","native_implemented":false,"timing_claim":false,"new_proofs":0,"proof_ledger":29953,"adopted":false,"goal_achieved":false});fs::write(format!("{R}/model.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Loose ordinary complex real square model PASS {all} outputs/{}rowidentities; exactS/D/9p2bound/closedREDC/no timing",all*5);}
